import { useState } from "react";
import LeaveService from "../Services/LeaveService";
import { useNavigate } from "react-router-dom";

const inputStyle = {
  width: '100%',
  padding: '11px 14px',
  border: '1.5px solid #e2e7f0',
  borderRadius: '8px',
  fontSize: '14px',
  fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
  color: '#1a1f36',
  background: '#fafbfd',
  outline: 'none',
  transition: 'border-color 0.2s, box-shadow 0.2s',
  boxSizing: 'border-box',
};

const labelStyle = {
  display: 'block',
  fontSize: '12px',
  fontWeight: '600',
  color: '#6b7694',
  marginBottom: '6px',
  letterSpacing: '0.5px',
  textTransform: 'uppercase',
};

const Leave = () => {
  const navigate = useNavigate();

  const [leave, setLeave] = useState({
    leaveType: '',
    startDate: '',
    endDate: '',
    reason: '',
    status: 'PENDING',
    employee: { id: '' },
  });

  const [focused, setFocused] = useState('');

  const change = (e) => {
    const { name, value } = e.target;
    if (name === 'id') setLeave({ ...leave, employee: { id: value } });
    else setLeave({ ...leave, [name]: value });
  };

  const save = (e) => {
    e.preventDefault();
    if (leave.endDate < leave.startDate) {
      alert('End date cannot be before start date');
      return;
    }
    LeaveService.createLeave(leave).then(() => {
      navigate('/dashboard', { state: { success: true } });
    });
  };

  const getFocusStyle = (field) => focused === field
    ? { borderColor: '#3b4784', boxShadow: '0 0 0 3px rgba(59,71,132,0.12)', background: '#fff' }
    : {};

  return (
    <div style={{
      background: '#fff',
      borderRadius: '16px',
      boxShadow: '0 4px 24px rgba(26,31,54,0.08)',
      overflow: 'hidden',
      fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
    }}>
      {/* Card Header */}
      <div style={{
        background: 'linear-gradient(135deg, #1a1f36 0%, #2d3561 100%)',
        padding: '24px 28px',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div style={{
            width: '32px', height: '32px', borderRadius: '8px',
            background: 'rgba(255,255,255,0.15)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
              <polyline points="14,2 14,8 20,8"/>
              <line x1="12" y1="18" x2="12" y2="12"/>
              <line x1="9" y1="15" x2="15" y2="15"/>
            </svg>
          </div>
          <div>
            <h2 style={{ margin: 0, fontSize: '16px', fontWeight: '700', color: '#fff', letterSpacing: '-0.2px' }}>
              Apply for Leave
            </h2>
            <p style={{ margin: 0, fontSize: '12px', color: 'rgba(255,255,255,0.6)', marginTop: '2px' }}>
              Fill in all required fields
            </p>
          </div>
        </div>
      </div>

      {/* Form Body */}
      <div style={{ padding: '28px' }}>
        <form onSubmit={save}>

          {/* Employee ID */}
          <div style={{ marginBottom: '18px' }}>
            <label style={labelStyle}>Employee ID</label>
            <input
              type="text"
              name="id"
              placeholder="e.g. EMP-1042"
              value={leave.employee.id}
              onChange={change}
              onFocus={() => setFocused('id')}
              onBlur={() => setFocused('')}
              style={{ ...inputStyle, ...getFocusStyle('id') }}
              required
            />
          </div>

          {/* Leave Type */}
          <div style={{ marginBottom: '18px' }}>
            <label style={labelStyle}>Leave Type</label>
            <div style={{ position: 'relative' }}>
              <select
                name="leaveType"
                value={leave.leaveType}
                onChange={change}
                onFocus={() => setFocused('leaveType')}
                onBlur={() => setFocused('')}
                style={{
                  ...inputStyle,
                  ...getFocusStyle('leaveType'),
                  appearance: 'none',
                  cursor: 'pointer',
                  paddingRight: '36px',
                  color: leave.leaveType ? '#1a1f36' : '#a0aabf',
                }}
                required
              >
                <option value="" disabled>Select leave type</option>
                <option value="sick leave">🤒  Sick Leave</option>
                <option value="holiday leave">🌴  Holiday Leave</option>
                <option value="earned leave">⭐  Earned Leave</option>
              </select>
              <svg style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none' }}
                width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#6b7694" strokeWidth="2.5" strokeLinecap="round">
                <polyline points="6,9 12,15 18,9"/>
              </svg>
            </div>
          </div>

          {/* Date Row */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '14px', marginBottom: '18px' }}>
            <div>
              <label style={labelStyle}>Start Date</label>
              <input
                type="date"
                name="startDate"
                value={leave.startDate}
                onChange={change}
                onFocus={() => setFocused('startDate')}
                onBlur={() => setFocused('')}
                style={{ ...inputStyle, ...getFocusStyle('startDate'), color: leave.startDate ? '#1a1f36' : '#a0aabf' }}
                required
              />
            </div>
            <div>
              <label style={labelStyle}>End Date</label>
              <input
                type="date"
                name="endDate"
                value={leave.endDate}
                onChange={change}
                onFocus={() => setFocused('endDate')}
                onBlur={() => setFocused('')}
                style={{ ...inputStyle, ...getFocusStyle('endDate'), color: leave.endDate ? '#1a1f36' : '#a0aabf' }}
                required
              />
            </div>
          </div>

          {/* Reason */}
          <div style={{ marginBottom: '28px' }}>
            <label style={labelStyle}>Reason <span style={{ color: '#b0bac8', fontWeight: 400, textTransform: 'none', letterSpacing: 0 }}>(optional)</span></label>
            <textarea
              name="reason"
              placeholder="Briefly describe the reason for your leave..."
              value={leave.reason}
              onChange={change}
              onFocus={() => setFocused('reason')}
              onBlur={() => setFocused('')}
              rows={3}
              style={{
                ...inputStyle,
                ...getFocusStyle('reason'),
                resize: 'vertical',
                minHeight: '80px',
                lineHeight: '1.5',
              }}
            />
          </div>

          {/* Divider */}
          <div style={{ borderTop: '1px solid #f0f2f8', marginBottom: '22px' }} />

          {/* Actions */}
          <div style={{ display: 'flex', gap: '12px' }}>
            <button
              type="submit"
              style={{
                flex: 1,
                background: 'linear-gradient(135deg, #1a1f36, #3b4784)',
                color: '#fff',
                border: 'none',
                padding: '12px',
                borderRadius: '8px',
                fontSize: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
                letterSpacing: '0.2px',
                transition: 'opacity 0.2s, transform 0.1s',
              }}
              onMouseEnter={e => e.target.style.opacity = '0.9'}
              onMouseLeave={e => e.target.style.opacity = '1'}
            >
              Submit Request
            </button>
            <button
              type="button"
              onClick={() => navigate('/')}
              style={{
                flex: 1,
                background: '#fff',
                color: '#4a5278',
                border: '1.5px solid #e2e7f0',
                padding: '12px',
                borderRadius: '8px',
                fontSize: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
                transition: 'background 0.2s, border-color 0.2s',
              }}
              onMouseEnter={e => { e.target.style.background = '#f7f9fc'; e.target.style.borderColor = '#c5cce0'; }}
              onMouseLeave={e => { e.target.style.background = '#fff'; e.target.style.borderColor = '#e2e7f0'; }}
            >
              Cancel
            </button>
          </div>

        </form>
      </div>
    </div>
  );
};

export default Leave;
